<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/include/bootstrap.php';

function subcategory_tenant_context(array $user): array
{
    if ((int)($user['role_type'] ?? 0) === 2) {
        json_error('Subcategory management is available only for tenant users.', 403);
    }
    $branchId = (int)($user['branch_id'] ?? 0);
    if ($branchId < 1) json_error('No active branch is assigned to your account.', 403);
    $stmt = db()->prepare(
        'SELECT b.id AS branch_id,b.company_id,b.branch_name,c.company_name
         FROM branches b INNER JOIN companies c ON c.id=b.company_id
         WHERE b.id=:branch_id AND b.status=1 AND c.status=1 LIMIT 1'
    );
    $stmt->execute([':branch_id'=>$branchId]);
    $row=$stmt->fetch();
    if(!$row) json_error('Your assigned tenant branch is invalid or inactive.',403);
    return ['branch_id'=>(int)$row['branch_id'],'company_id'=>(int)$row['company_id'],'branch_name'=>(string)$row['branch_name'],'company_name'=>(string)$row['company_name']];
}

function subcategory_text($value,string $field,string $label,int $max): string
{
    $value=trim((string)($value??''));
    if($value==='') json_error($label.' is required.',422,[$field=>$label.' is required.']);
    if(mb_strlen($value)>$max) json_error($label.' is too long.',422,[$field=>$label.' must be within '.$max.' characters.']);
    return $value;
}


function subcategory_generate_code(int $branchId): string{$s=db()->prepare("SELECT sc.subcategory_code FROM subcategories sc INNER JOIN categories c ON c.id=sc.category_id WHERE c.branch_id=:branch_id AND sc.subcategory_code REGEXP '^SUB[0-9]+$' ORDER BY CAST(SUBSTRING(sc.subcategory_code,4) AS UNSIGNED) DESC LIMIT 1");$s->execute([':branch_id'=>$branchId]);$last=(string)($s->fetchColumn()?:'');$n=1;if($last!==''&&preg_match('/^SUB([0-9]+)$/i',$last,$m))$n=(int)$m[1]+1;return 'SUB'.str_pad((string)$n,4,'0',STR_PAD_LEFT);}
function subcategory_category(int $branchId,int $categoryId): array{$s=db()->prepare('SELECT id,category_code,category_name FROM categories WHERE id=:id AND branch_id=:branch_id AND status=1 LIMIT 1');$s->execute([':id'=>$categoryId,':branch_id'=>$branchId]);$r=$s->fetch();if(!$r)json_error('Select an active Category from your branch.',422,['category_id'=>'Select a valid active Category.']);return $r;}
function subcategory_record(int $branchId,int $id): array{$s=db()->prepare('SELECT sc.id,sc.category_id,sc.subcategory_code,sc.subcategory_name,sc.status,sc.created_by,sc.created_at,sc.updated_at,c.category_code,c.category_name,c.branch_id FROM subcategories sc INNER JOIN categories c ON c.id=sc.category_id WHERE sc.id=:id AND c.branch_id=:branch_id LIMIT 1');$s->execute([':id'=>$id,':branch_id'=>$branchId]);$r=$s->fetch();if(!$r)json_error('Subcategory was not found in your branch.',404);foreach(['id','category_id','branch_id','status'] as $k)$r[$k]=(int)$r[$k];return $r;}
function subcategory_unique(int $branchId,int $categoryId,string $name,int $exclude=0): void{$sql='SELECT sc.id FROM subcategories sc INNER JOIN categories c ON c.id=sc.category_id WHERE c.branch_id=:branch_id AND sc.category_id=:category_id AND LOWER(sc.subcategory_name)=LOWER(:name)';$p=[':branch_id'=>$branchId,':category_id'=>$categoryId,':name'=>$name];if($exclude>0){$sql.=' AND sc.id<>:id';$p[':id']=$exclude;}$sql.=' LIMIT 1';$s=db()->prepare($sql);$s->execute($p);if($s->fetchColumn())json_error('Subcategory name already exists under this Category.',409,['subcategory_name'=>'Use a unique Subcategory name for this Category.']);}
function subcategory_status($v): int{$n=(int)$v;if(!in_array($n,[1,2],true))json_error('Invalid Subcategory status.',422,['status'=>'Status must be Active or Inactive.']);return $n;}
