y_name'.$base.' WHERE '.implode(' AND ',$where).' ORDER BY '.$order.' '.$dir.',sc.id ASC LIMIT :start,:length';$s=db()->prepare($sql);foreach($p as $k=>$v)$s->bindValue($k,$v,($k===':branch_id'||$k===':status')?PDO::PARAM_INT:PDO::PARAM_STR);$s->bindValue(':start',$start,PDO::PARAM_INT);$s->bindValue(':length',$length,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();foreach($rows as &$r){$r['id']=(int)$r['id'];$r['category_id']=(int)$r['category_id'];$r['status']=(int)$r['status'];}unset($r);json_success('Subcategories loaded.',['datatable'=>['draw'=>$draw,'recordsTotal'=>$total,'recordsFiltered'=>$filtered,'data'=>$rows],'allowed_actions'=>$access['actions']]);}$sql='SELECT sc.id,sc.category_id,sc.subcategory_code,sc.subcategory_name,sc.status,c.category_name FROM subcategories sc INNER JOIN categories c ON c.id=sc.category_id WHERE c.branch_id=:branch_id';if(isset($_GET['active'])&&(int)$_GET['active']===1)$sql.=' AND sc.status=1 AND c.status=1';$sql.=' ORDER BY c.category_name,sc.subcategory_name';$s=db()->prepare($sql);$s->execute([':branch_id'=>$b]);json_success('Subcategories loaded.',['subcategories'=>$s->fetchAll(),'allowed_actions'=>$access['actions']]);}
if($method==='POST'){$access=require_permission('subcategory-list.php',ACTION_CREATE);$u=$access['user'];$ctx=subcategory_tenant_context($u);$b=$ctx['branch_id'];$d=request_data();$cat=positive_id($d['category_id']??0,'category_id');subcategory_category($b,$cat);$name=subcategory_text($d['subcategory_name']??'','subcategory_name','Subcategory name',120);subcategory_unique($b,$cat,$name);$code=subcategory_generate_code($b);$s=db()->prepare('INSERT INTO subcategories(category_id,subcategory_code,subcategory_name,status,created_by,created_at,updated_at) VALUES(:category_id,:code,:name,1,:created_by,NOW(),NOW())');$s->execute([':category_id'=>$cat,':code'=>$code,':name'=>$name,':created_by'=>(int)$u['id']]);$id=(int)db()->lastInsertId();audit_log((int)$u['id'],ACTION_CREATE,['company_id'=>$ctx['company_id'],'branch_id'=>$b,'menu_id'=>(int)$access['menu']['id'],'record_id'=>$id]);json_success('Subcategory created successfully.',['subcategory'=>subcategory_record($b,$id)],201);}
