if($method==='PATCH'){$d=request_data();require_fields($d,['id','status']);$status=subcategory_status($d['status']);$access=require_permission('subcategory-list.php',$status===1?ACTION_ACTIVATE:ACTION_DEACTIVATE);$u=$access['user'];$ctx=subcategory_tenant_context($u);$b=$ctx['branch_id'];$id=positive_id($d['id']);$old=subcategory_record($b,$id);db()->prepare('UPDATE subcategories SET status=:status,updated_at=NOW() WHERE id=:id')->execute([':status'=>$status,':id'=>$id]);audit_log((int)$u['id'],$status===1?ACTION_ACTIVATE:ACTION_DEACTIVATE,['company_id'=>$ctx['company_id'],'branch_id'=>$b,'menu_id'=>(int)$access['menu']['id'],'record_id'=>$id,'old_data'=>$old]);json_success($status===1?'Subcategory activated.':'Subcategory deactivated.');}
